import './styles.css';
import { Controls, Time as TimePrimitive, Tooltip } from "@videojs/react";
import { FullscreenButton } from "./components/fullscreen-button/fullscreen-button";
import { PlayButton } from "./components/play-button/play-button";
import { SeekButton } from "./components/seek-button/seek-button";
import { VolumePopover } from "./components/volume-popover/volume-popover";
import { TimeSlider } from "./components/time-slider/time-slider";
const SEEK_SECONDS = 10;
export function DefaultVideoSkin() {
    return (<Controls.Root className="media-skin media-theme-default">
      <Tooltip.Provider>
        <Controls.Group className="media-controls-group-primary">
          <PlayButton />
          <SeekButton seconds={-SEEK_SECONDS}/>
          <SeekButton seconds={SEEK_SECONDS}/>
        </Controls.Group>

        <Controls.Group className="media-controls-group-time">
          <TimePrimitive.Value className="media-time" type="current"/>
          <TimeSlider />
          <TimePrimitive.Value className="media-time" type="remaining" toggle/>
        </Controls.Group>

        <Controls.Group className="media-controls-group-primary">
          <VolumePopover />
          <FullscreenButton />
        </Controls.Group>
      </Tooltip.Provider>
    </Controls.Root>);
}

@import './styles/base.css';
@import './styles/themes/default.css';

.media-controls-group-primary {
  align-items: center;
  gap: var(--media-controls-gap);
  display: flex;
}

.media-controls-group-time {
  align-items: center;
  gap: var(--media-controls-gap);
  flex: 1;
  display: flex;
}

.media-skin {
  align-items: center;
  gap: var(--media-controls-gap);
  border-radius: var(--media-radius-pill);
  background-color: var(--media-surface-background);
  padding: var(--media-controls-padding);
  font-family: var(--media-font-family);
  font-size: var(--media-font-size);
  color: var(--media-controls-color);
  box-shadow: 0 0 #0000, 0 0 #0000, 0 0 #0000, 0 0 #0000, 0 0 0 1px var(--media-surface-border), 0 2px 8px var(--media-shadow-color);
  backdrop-filter: blur(var(--media-surface-backdrop-blur));
  line-height: 1;
  display: flex;
}

.media-time {
  font-variant-numeric: tabular-nums;
}

@layer videojs.base {
  .media-skin,
  .media-skin *,
  .media-skin *::before,
  .media-skin *::after {
    box-sizing: border-box;
  }
}

@layer videojs.theme {
  .media-theme-default {
    --media-controls-color: oklch(1 0 0);
    --media-controls-gap: 0.25rem;
    --media-controls-padding: 0.25rem;
    --media-control-size: 2.25rem;
    --media-control-hover-background: oklch(1 0 0 / 0.12);
    --media-font-family: ui-sans-serif, system-ui, sans-serif;
    --media-font-size: 0.875rem;
    --media-icon-size: 1.125rem;
    --media-radius-pill: 9999px;
    --media-radius-surface: 0.5rem;
    --media-shadow-color: oklch(0 0 0 / 0.35);
    --media-slider-buffer-background: oklch(1 0 0 / 0.3);
    --media-slider-thumb-size: 0.75rem;
    --media-slider-track-background: oklch(1 0 0 / 0.2);
    --media-slider-track-size: 0.25rem;
    --media-surface-backdrop-blur: 12px;
    --media-surface-background: oklch(0.2 0 0 / 0.72);
    --media-surface-border: oklch(1 0 0 / 0.16);
  }
}

import './styles.css';
import { Tooltip as TooltipPrimitive } from "@videojs/react";
import type { ReactElement } from "react";
export interface ButtonTooltipProps extends TooltipPrimitive.RootProps {
