  width: var(--media-icon-size);
  height: var(--media-icon-size);
  opacity: 0;
  filter: drop-shadow(0 1px 0 var(--media-shadow-color));
  display: none;
}

.media-fullscreen-button-icon-enter:is(:where(.media-fullscreen-button):not([data-fullscreen]) *) {
  opacity: 1;
  display: block;
}

.media-fullscreen-button-icon-exit {
  width: var(--media-icon-size);
  height: var(--media-icon-size);
  opacity: 0;
  filter: drop-shadow(0 1px 0 var(--media-shadow-color));
  display: none;
}

.media-fullscreen-button-icon-exit:is(:where(.media-fullscreen-button)[data-fullscreen] *) {
  opacity: 1;
  display: block;
}

