@import '../../styles/base.css';
@import '../../styles/themes/default.css';

.media-slider {
  min-height: var(--media-control-size);
  cursor: pointer;
  outline-style: none;
  flex: 1;
  justify-content: center;
  align-items: center;
  min-width: 5rem;
  display: flex;
  position: relative;
}

.media-slider[data-orientation="vertical"] {
  height: 5rem;
  width: var(--media-control-size);
  min-width: 0;
}

.media-slider-buffer {
  width: var(--media-slider-buffer);
  border-radius: inherit;
  background-color: var(--media-slider-buffer-background);
  inset-block: 0;
  position: absolute;
  left: 0;
}

.media-slider-buffer[data-orientation="vertical"] {
  height: var(--media-slider-buffer);
  inset-inline: 0;
  width: auto;
  top: auto;
  bottom: 0;
}

.media-slider-fill {
  width: var(--media-slider-fill);
  border-radius: inherit;
  inset-block: 0;
  background-color: currentColor;
  position: absolute;
  left: 0;
}

.media-slider-fill[data-orientation="vertical"] {
  height: var(--media-slider-fill);
  inset-inline: 0;
  width: auto;
  top: auto;
  bottom: 0;
}

.media-slider-preview {
  position: relative;
}

.media-slider-thumb {
  top: 50%;
  left: var(--media-slider-fill);
  width: var(--media-slider-thumb-size);
  height: var(--media-slider-thumb-size);
  translate: calc(calc(1 / 2 * 100.0%) * -1) calc(calc(1 / 2 * 100.0%) * -1);
  border-radius: var(--media-radius-pill);
  background-color: currentColor;
  position: absolute;
}

.media-slider-thumb[data-orientation="vertical"] {
  top: calc(100.0% - var(--media-slider-fill));
  left: 50%;
}

.media-slider-track {
  height: var(--media-slider-track-size);
  border-radius: var(--media-radius-pill);
  background-color: var(--media-slider-track-background);
  width: 100%;
  position: relative;
  overflow: hidden;
}

.media-slider-track[data-orientation="vertical"] {
  height: 100%;
  width: var(--media-slider-track-size);
}

.media-slider-value {
  font-variant-numeric: tabular-nums;
}

.media-spinner-icon {
  width: var(--media-icon-size);
  height: var(--media-icon-size);
  filter: drop-shadow(0 1px 0 var(--media-shadow-color));
}

.media-thumbnail {
  border-radius: var(--media-radius-surface);
  background-color: var(--media-surface-background);
  color: var(--media-controls-color);
  box-shadow: 0 0 #0000, 0 0 #0000, 0 0 #0000, 0 0 #0000, 0 0 0 1px var(--media-surface-border), 0 2px 8px var(--media-shadow-color);
  backdrop-filter: blur(var(--media-surface-backdrop-blur));
  position: absolute;
  bottom: calc(100% + .75rem);
  overflow: hidden;
}

.media-thumbnail-image {
  max-width: 12rem;
  max-height: 7rem;
  display: block;
}

import './styles.css';
import { Slider, TimeSlider as TimeSliderPrimitive } from "@videojs/react";
import { SpinnerIcon } from "@videojs/react/icons";
export function TimeSlider() {
    return (<TimeSliderPrimitive.Root className="media-slider" thumbAlignment="edge">
      <TimeSliderPrimitive.Track className="media-slider-track">
        <TimeSliderPrimitive.Fill className="media-slider-fill"/>
        <TimeSliderPrimitive.Buffer className="media-slider-buffer"/>
      </TimeSliderPrimitive.Track>
      <TimeSliderPrimitive.Thumb className="media-slider-thumb"/>
      <div className="media-thumbnail">
        <Slider.Thumbnail className="media-thumbnail-image"/>
        <TimeSliderPrimitive.Value className="media-slider-value" type="pointer"/>
        <SpinnerIcon className="media-spinner-icon"/>
      </div>
      <TimeSliderPrimitive.Preview className="media-slider-preview">
        <TimeSliderPrimitive.Value className="media-slider-value" type="pointer"/>
      </TimeSliderPrimitive.Preview>
    </TimeSliderPrimitive.Root>);
}

